<script>
(function () {
  "use strict";

  // ---------------------------------------------------------------------
  // Constants
  // ---------------------------------------------------------------------
  const MEM_SIZE = 4096;
  const PROGRAM_START = 0x200;
  const FONT_START = 0x050;
  const DISPLAY_W = 64;
  const DISPLAY_H = 32;
  const SCALE = 10;

  const FONTSET = new Uint8Array([
    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
    0x20, 0x60, 0x20, 0x20, 0x70, // 1
    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
    0x90, 0x90, 0xF0, 0x10, 0x10, // 4
    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
    0xF0, 0x80, 0xF0, 0x80, 0x80  // F
  ]);

  // Keypad layout mapping: physical key -> chip8 hex key
  const KEYMAP = {
    'Digit1': 0x1, 'Digit2': 0x2, 'Digit3': 0x3, 'Digit4': 0xC,
    'KeyQ': 0x4, 'KeyW': 0x5, 'KeyE': 0x6, 'KeyR': 0xD,
    'KeyA': 0x7, 'KeyS': 0x8, 'KeyD': 0x9, 'KeyF': 0xE,
    'KeyZ': 0xA, 'KeyX': 0x0, 'KeyC': 0xB, 'KeyV': 0xF
  };
  // Layout for the on-screen 4x4 keypad (in CHIP-8 hex key order)
  const KEYPAD_LAYOUT = [
    0x1, 0x2, 0x3, 0xC,
    0x4, 0x5, 0x6, 0xD,
    0x7, 0x8, 0x9, 0xE,
    0xA, 0x0, 0xB, 0xF
  ];

  // ---------------------------------------------------------------------
  // Demo ROM — hand assembled.
  // Draws a 5x5 box sprite at (5,5). Waits for a key press. If the key
  // pressed is '6' (physical 'E' key) it erases, moves the sprite one
  // pixel right, and redraws; any other key simply redraws in place.
  //
  // Assembly:
  //   200: 6005        LD   V0, 0x05        ; x = 5
  //   202: 6105        LD   V1, 0x05        ; y = 5
  //   204: A300         LD   I, 0x300        ; sprite address
  //   206: D015        LOOP: DRW  V0,V1,5    ; draw sprite
  //   208: F20A        LD   V2, K           ; block until key pressed -> V2
  //   20A: D015        DRW  V0,V1,5          ; erase sprite at old pos
  //   20C: 4206        SNE  V2, 0x06         ; if V2 != 6 skip next
  //   20E: 7001        ADD  V0, 0x01         ; x += 1  (only if key==6)
  //   210: 1206        JP   0x206            ; loop back
  //   ...
  //   300: F0 90 90 90 F0                    ; sprite data (5x5 box)
  // ---------------------------------------------------------------------
  function buildDemoRom() {
    const rom = new Uint8Array(0x105); // offsets relative to 0x200
    const instr = [
      0x60, 0x05,
      0x61, 0x05,
      0xA3, 0x00,
      0xD0, 0x15,
      0xF2, 0x0A,
      0xD0, 0x15,
      0x42, 0x06,
      0x70, 0x01,
      0x12, 0x06
    ];
    rom.set(instr, 0x000);
    rom.set([0xF0, 0x90, 0x90, 0x90, 0xF0], 0x100);
    return rom;
  }
  const DEMO_ROM = buildDemoRom();

  // ---------------------------------------------------------------------
  // CHIP-8 core
  // ---------------------------------------------------------------------
  class Chip8 {
    constructor() {
      this.reset();
    }

    reset() {
      this.memory = new Uint8Array(MEM_SIZE);
      this.memory.set(FONTSET, FONT_START);
      this.V = new Uint8Array(16);
      this.I = 0;
      this.pc = PROGRAM_START;
      this.stack = [];
      this.delayTimer = 0;
      this.soundTimer = 0;
      this.display = new Uint8Array(DISPLAY_W * DISPLAY_H);
      this.keys = new Uint8Array(16);
      this.waitingForKey = false;
      this.waitKeyRegister = -1;
      this.drawFlag = true;
      this.lastInstrText = '--';
      this.romLoaded = false;
      this.romBytes = null;
    }

    loadRom(bytes) {
      this.reset();
      const limit = Math.min(bytes.length, MEM_SIZE - PROGRAM_START);
      for (let i = 0; i < limit; i++) {
        this.memory[PROGRAM_START + i] = bytes[i];
      }
      this.romLoaded = true;
      this.romBytes = bytes;
    }

    // decode-only, used for debugger display without mutating state
    decodeAt(addr) {
      if (addr + 1 >= MEM_SIZE) return '--';
      const opcode = (this.memory[addr] << 8) | this.memory[addr + 1];
      return Chip8.disassemble(opcode);
    }

    static disassemble(opcode) {
      const nnn = opcode & 0x0FFF;
      const n = opcode & 0x000F;
      const x = (opcode & 0x0F00) >> 8;
      const y = (opcode & 0x00F0) >> 4;
      const kk = opcode & 0x00FF;
      switch (opcode & 0xF000) {
        case 0x0000:
          if (opcode === 0x00E0) return 'CLS';
          if (opcode === 0x00EE) return 'RET';
          return `SYS 0x${nnn.toString(16)}`;
        case 0x1000: return `JP 0x${nnn.toString(16)}`;
        case 0x2000: return `CALL 0x${nnn.toString(16)}`;
        case 0x3000: return `SE V${x.toString(16)}, 0x${kk.toString(16)}`;
        case 0x4000: return `SNE V${x.toString(16)}, 0x${kk.toString(16)}`;
        case 0x5000: return `SE V${x.toString(16)}, V${y.toString(16)}`;
        case 0x6000: return `LD V${x.toString(16)}, 0x${kk.toString(16)}`;
        case 0x7000: return `ADD V${x.toString(16)}, 0x${kk.toString(16)}`;
        case 0x8000:
          switch (n) {
            case 0x0: return `LD V${x.toString(16)}, V${y.toString(16)}`;
            case 0x1: return `OR V${x.toString(16)}, V${y.toString(16)}`;
            case 0x2: return `AND V${x.toString(16)}, V${y.toString(16)}`;
            case 0x3: return `XOR V${x.toString(16)}, V${y.toString(16)}`;
            case 0x4: return `ADD V${x.toString(16)}, V${y.toString(16)}`;
            case 0x5: return `SUB V${x.toString(16)}, V${y.toString(16)}`;
            case 0x6: return `SHR V${x.toString(16)}`;
            case 0x7: return `SUBN V${x.toString(16)}, V${y.toString(16)}`;
            case 0xE: return `SHL V${x.toString(16)}`;
            default: return `??? 0x${opcode.toString(16)}`;
          }
        case 0x9000: return `SNE V${x.toString(16)}, V${y.toString(16)}`;
        case 0xA000: return `LD I, 0x${nnn.toString(16)}`;
        case 0xB000: return `JP V0, 0x${nnn.toString(16)}`;
        case 0xC000: return `RND V${x.toString(16)}, 0x${kk.toString(16)}`;
        case 0xD000: return `DRW V${x.toString(16)}, V${y.toString(16)}, ${n}`;
        case 0xE000:
          if (kk === 0x9E) return `SKP V${x.toString(16)}`;
          if (kk === 0xA1) return `SKNP V${x.toString(16)}`;
          return `??? 0x${opcode.toString(16)}`;
        case 0xF000:
          switch (kk) {
            case 0x07: return `LD V${x.toString(16)}, DT`;
            case 0x0A: return `LD V${x.toString(16)}, K`;
            case 0x15: return `LD DT, V${x.toString(16)}`;
            case 0x18: return `LD ST, V${x.toString(16)}`;
            case 0x1E: return `ADD I, V${x.toString(16)}`;
            case 0x29: return `LD F, V${x.toString(16)}`;
            case 0x33: return `LD B, V${x.toString(16)}`;
            case 0x55: return `LD [I], V${x.toString(16)}`;
            case 0x65: return `LD V${x.toString(16)}, [I]`;
            default: return `??? 0x${opcode.toString(16)}`;
          }
        default: return `??? 0x${opcode.toString(16)}`;
      }
    }

    // Execute a single instruction (fetch-decode-execute)
    step() {
      if (this.waitingForKey) {
        // Stay blocked until a key is pressed (handled in onKeyDown)
        this.lastInstrText = this.decodeAt(this.pc) + '  (waiting for key)';
        return;
      }

      const opcode = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
      this.lastInstrText = Chip8.disassemble(opcode);
      this.pc += 2;

      const nnn = opcode & 0x0FFF;
      const n = opcode & 0x000F;
      const x = (opcode & 0x0F00) >> 8;
      const y = (opcode & 0x00F0) >> 4;
      const kk = opcode & 0x00FF;

      switch (opcode & 0xF000) {
        case 0x0000:
          if (opcode === 0x00E0) {
            this.display.fill(0);
            this.drawFlag = true;
          } else if (opcode === 0x00EE) {
            this.pc = this.stack.pop();
          }
          // 0x0NNN (SYS) ignored on modern interpreters
          break;

        case 0x1000: // JP addr
          this.pc = nnn;
          break;

        case 0x2000: // CALL addr
          this.stack.push(this.pc);
          this.pc = nnn;
          break;

        case 0x3000: // SE Vx, kk
          if (this.V[x] === kk) this.pc += 2;
          break;

        case 0x4000: // SNE Vx, kk
          if (this.V[x] !== kk) this.pc += 2;
          break;

        case 0x5000: // SE Vx, Vy
          if (this.V[x] === this.V[y]) this.pc += 2;
          break;

        case 0x6000: // LD Vx, kk
          this.V[x] = kk;
          break;

        case 0x7000: // ADD Vx, kk
          this.V[x] = (this.V[x] + kk) & 0xFF;
          break;

        case 0x8000:
          switch (n) {
            case 0x0: this.V[x] = this.V[y]; break;
            case 0x1: this.V[x] = this.V[x] | this.V[y]; this.V[0xF] = 0; break;
            case 0x2: this.V[x] = this.V[x] & this.V[y]; this.V[0xF] = 0; break;
            case 0x3: this.V[x] = this.V[x] ^ this.V[y]; this.V[0xF] = 0; break;
            case 0x4: {
              const sum = this.V[x] + this.V[y];
              const carry = sum > 0xFF ? 1 : 0;
              this.V[x] = sum & 0xFF;
              this.V[0xF] = carry;
              break;
            }
            case 0x5: {
              const notBorrow = this.V[x] >= this.V[y] ? 1 : 0;
              const r = (this.V[x] - this.V[y]) & 0xFF;
              this.V[x] = r;
              this.V[0xF] = notBorrow;
              break;
            }
            case 0x6: {
              const lsb = this.V[x] & 0x1;
              this.V[x] = this.V[x] >> 1;
              this.V[0xF] = lsb;
              break;
            }
            case 0x7: {
              const notBorrow = this.V[y] >= this.V[x] ? 1 : 0;
              const r = (this.V[y] - this.V[x]) & 0xFF;
              this.V[x] = r;
              this.V[0xF] = notBorrow;
              break;
            }
            case 0xE: {
              const msb = (this.V[x] & 0x80) >> 7;
              this.V[x] = (this.V[x] << 1) & 0xFF;
              this.V[0xF] = msb;
              break;
            }
          }
          break;

        case 0x9000: // SNE Vx, Vy
          if (this.V[x] !== this.V[y]) this.pc += 2;
          break;

        case 0xA000: // LD I, addr
          this.I = nnn;
          break;

        case 0xB000: // JP V0, addr
          this.pc = (nnn + this.V[0]) & 0x0FFF;
          break;

        case 0xC000: // RND Vx, kk
          this.V[x] = (Math.floor(Math.random() * 256)) & kk;
          break;

        case 0xD000: { // DRW Vx, Vy, n
          const sx = this.V[x] % DISPLAY_W;
          const sy = this.V[y] % DISPLAY_H;
          this.V[0xF] = 0;
          for (let row = 0; row < n; row++) {
            const spriteByte = this.memory[this.I + row];
            if (sy + row >= DISPLAY_H) break;
            for (let col = 0; col < 8; col++) {
              if (sx + col >= DISPLAY_W) break;
              const bit = (spriteByte >> (7 - col)) & 0x1;
              if (bit === 0) continue;
              const idx = (sy + row) * DISPLAY_W + (sx + col);
              if (this.display[idx] === 1) {
                this.V[0xF] = 1;
              }
              this.display[idx] ^= 1;
            }
          }
          this.drawFlag = true;
          break;
        }

        case 0xE000:
          if (kk === 0x9E) { // SKP Vx
            if (this.keys[this.V[x] & 0xF]) this.pc += 2;
          } else if (kk === 0xA1) { // SKNP Vx
            if (!this.keys[this.V[x] & 0xF]) this.pc += 2;
          }
          break;

        case 0xF000:
          switch (kk) {
            case 0x07: this.V[x] = this.delayTimer; break;
            case 0x0A:
              this.waitingForKey = true;
              this.waitKeyRegister = x;
              break;
            case 0x15: this.delayTimer = this.V[x]; break;
            case 0x18: this.soundTimer = this.V[x]; break;
            case 0x1E: {
              const sum = this.I + this.V[x];
              this.V[0xF] = sum > 0x0FFF ? 1 : 0;
              this.I = sum & 0x0FFF;
              break;
            }
            case 0x29: this.I = FONT_START + (this.V[x] & 0xF) * 5; break;
            case 0x33: {
              const val = this.V[x];
              this.memory[this.I] = Math.floor(val / 100);
              this.memory[this.I + 1] = Math.floor((val % 100) / 10);
              this.memory[this.I + 2] = val % 10;
              break;
            }
            case 0x55:
              for (let i = 0; i <= x; i++) this.memory[this.I + i] = this.V[i];
              this.I = (this.I + x + 1) & 0x0FFF;
              break;
            case 0x65:
              for (let i = 0; i <= x; i++) this.V[i] = this.memory[this.I + i];
              this.I = (this.I + x + 1) & 0x0FFF;
              break;
          }
          break;
      }
    }

    onKeyDown(hexKey) {
      this.keys[hexKey] = 1;
      if (this.waitingForKey) {
        this.V[this.waitKeyRegister] = hexKey;
        this.waitingForKey = false;
        this.waitKeyRegister = -1;
      }
    }

    onKeyUp(hexKey) {
      this.keys[hexKey] = 0;
    }

    tickTimers() {
      if (this.delayTimer > 0) this.delayTimer--;
      if (this.soundTimer > 0) this.soundTimer--;
    }
  }

  // ---------------------------------------------------------------------
  // UI / driver
  // ---------------------------------------------------------------------
  const chip8 = new Chip8();
  chip8.loadRom(DEMO_ROM);

  const canvas = document.getElementById('screen');
  const ctx = canvas.getContext('2d');
  canvas.width = DISPLAY_W * SCALE;
  canvas.height = DISPLAY_H * SCALE;

  let running = false;
  let instructionsPerFrame = 8;
  let lastTimerTick = 0;
  let audioCtx = null;
  let oscillator = null;

  function ensureAudio() {
    if (!audioCtx) {
      try {
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      } catch (e) {
        audioCtx = null;
      }
    }
  }

  function startBeep() {
    if (!document.getElementById('soundToggle').checked) return;
    ensureAudio();
    if (!audioCtx || oscillator) return;
    oscillator = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    gain.gain.value = 0.05;
    oscillator.type = 'square';
    oscillator.frequency.value = 440;
    oscillator.connect(gain);
    gain.connect(audioCtx.destination);
    oscillator.start();
    oscillator._gain = gain;
  }

  function stopBeep() {
    if (oscillator) {
      try { oscillator.stop(); } catch (e) { /* ignore */ }
      oscillator.disconnect();
      oscillator = null;
    }
  }

  function render() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#9fe39f';
    for (let y = 0; y < DISPLAY_H; y++) {
      for (let x = 0; x < DISPLAY_W; x++) {
        if (chip8.display[y * DISPLAY_W + x]) {
          ctx.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
        }
      }
    }
  }

  function updateDebugger() {
    const regTable = document.getElementById('regTable');
    regTable.innerHTML = '<tr><th>Reg</th><th>Val</th></tr>';
    for (let i = 0; i < 16; i++) {
      const tr = document.createElement('tr');
      const regName = 'V' + i.toString(16).toUpperCase();
      const hexVal = '0x' + chip8.V[i].toString(16).padStart(2, '0');
      tr.innerHTML = `<td>${regName}</td><td>${hexVal} (${chip8.V[i]})</td>`;
      regTable.appendChild(tr);
    }
    document.getElementById('dbgPC').textContent = '0x' + chip8.pc.toString(16).padStart(3, '0');
    document.getElementById('dbgI').textContent = '0x' + chip8.I.toString(16).padStart(3, '0');
    document.getElementById('dbgDT').textContent = chip8.delayTimer;
    document.getElementById('dbgST').textContent = chip8.soundTimer;
    document.getElementById('dbgSP').textContent = chip8.stack.length;

    const stackList = document.getElementById('stackList');
    if (chip8.stack.length === 0) {
      stackList.textContent = '(empty)';
    } else {
      stackList.innerHTML = chip8.stack
        .map((v, i) => `#${i}: 0x${v.toString(16).padStart(3, '0')}`)
        .join('<br>');
    }

    document.getElementById('currentInstr').textContent =
      'Instr @ 0x' + chip8.pc.toString(16).padStart(3, '0') + ': ' + chip8.decodeAt(chip8.pc);

    document.getElementById('statusBar').textContent =
      'Status: ' + (running ? 'running' : 'stopped') +
      (chip8.waitingForKey ? ' (waiting for key input)' : '');
  }

  function updateKeypadVisual() {
    for (let hex = 0; hex < 16; hex++) {
      const el = document.getElementById('key-' + hex.toString(16));
      if (el) el.classList.toggle('active', !!chip8.keys[hex]);
    }
  }

  let frameAccumulatorMs = 0;
  let lastFrameTime = null;

  function frameLoop(timestamp) {
    if (!running) return;
    if (lastFrameTime === null) lastFrameTime = timestamp;
    const dt = timestamp - lastFrameTime;
    lastFrameTime = timestamp;
    frameAccumulatorMs += dt;

    // 60 Hz timer / frame cadence
    const frameInterval = 1000 / 60;
    while (frameAccumulatorMs >= frameInterval) {
      for (let i = 0; i < instructionsPerFrame; i++) {
        if (!chip8.waitingForKey) chip8.step();
        else break;
      }
      chip8.tickTimers();
      frameAccumulatorMs -= frameInterval;
    }

    if (chip8.soundTimer > 0) startBeep(); else stopBeep();

    render();
    updateDebugger();
    updateKeypadVisual();

    requestAnimationFrame(frameLoop);
  }

  function startRunning() {
    if (running) return;
    running = true;
    lastFrameTime = null;
    frameAccumulatorMs = 0;
    requestAnimationFrame(frameLoop);
  }

  function pauseRunning() {
    running = false;
    stopBeep();
    updateDebugger();
  }

  function singleStep() {
    running = false;
    stopBeep();
    if (!chip8.waitingForKey) chip8.step();
    chip8.tickTimers();
    render();
    updateDebugger();
    updateKeypadVisual();
  }

  function resetEmu() {
    running = false;
    stopBeep();
    const bytes = chip8.romBytes || DEMO_ROM;
    chip8.loadRom(bytes);
    render();
    updateDebugger();
    updateKeypadVisual();
  }

  // ---- Controls wiring ----
  document.getElementById('btnRun').addEventListener('click', startRunning);
  document.getElementById('btnPause').addEventListener('click', pauseRunning);
  document.getElementById('btnStep').addEventListener('click', singleStep);
  document.getElementById('btnReset').addEventListener('click', resetEmu);
  document.getElementById('btnLoadDemo').addEventListener('click', function () {
    running = false;
    stopBeep();
    chip8.loadRom(DEMO_ROM);
    render();
    updateDebugger();
  });

  document.getElementById('speed').addEventListener('input', function (e) {
    instructionsPerFrame = parseInt(e.target.value, 10);
    document.getElementById('speedVal').textContent = instructionsPerFrame;
  });

  document.getElementById('fileInput').addEventListener('change', function (e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function (ev) {
      const bytes = new Uint8Array(ev.target.result);
      running = false;
      stopBeep();
      chip8.loadRom(bytes);
      render();
      updateDebugger();
    };
    reader.readAsArrayBuffer(file);
  });

  // ---- On-screen keypad ----
  const keypadEl = document.getElementById('keypad');
  KEYPAD_LAYOUT.forEach(function (hex) {
    const div = document.createElement('div');
    div.className = 'key';
    div.id = 'key-' + hex.toString(16);
    div.textContent = hex.toString(16).toUpperCase();

    const press = function (ev) {
      ev.preventDefault();
      chip8.onKeyDown(hex);
      updateKeypadVisual();
    };
    const release = function (ev) {
      ev.preventDefault();
      chip8.onKeyUp(hex);
      updateKeypadVisual();
    };

    div.addEventListener('mousedown', press);
    div.addEventListener('mouseup', release);
    div.addEventListener('mouseleave', release);
    div.addEventListener('touchstart', press, { passive: false });
    div.addEventListener('touchend', release, { passive: false });

    keypadEl.appendChild(div);
  });

  // ---- Physical keyboard ----
  window.addEventListener('keydown', function (e) {
    if (e.code in KEYMAP) {
      chip8.onKeyDown(KEYMAP[e.code]);
      updateKeypadVisual();
    }
  });
  window.addEventListener('keyup', function (e) {
    if (e.code in KEYMAP) {
      chip8.onKeyUp(KEYMAP[e.code]);
      updateKeypadVisual();
    }
  });

  // ---- Initial paint ----
  render();
  updateDebugger();
  updateKeypadVisual();
})();
</script>
</body>
</html>
